/* @autogenerated */
package net.civeira.phylax.integrationtest.feature.oauth.flow;

import java.net.URI;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import io.restassured.response.Response;
import net.civeira.phylax.integrationtest.feature.oauth.fixtures.OidcTestFixtures;

/** The OP iframe checks an RP's registered origin and the public sid across cookie rotation. */
@Tag("oidc-flow")
@QuarkusTest
class SessionStateFlowTest extends OidcIntegrationTestBase {
  private static final String BASE = "/oauth/openid/" + OidcTestFixtures.TENANT;

  private String sessionState(Response authorization) {
    String query = URI.create(authorization.getHeader("Location")).getRawQuery();
    for (String part : query.split("&")) {
      if (part.startsWith("session_state=")) {
        return URLDecoder.decode(part.substring(14), StandardCharsets.UTF_8);
      }
    }
    throw new AssertionError("session_state missing: " + query);
  }

  private String check(String cookie, String origin, String clientId, String state) {
    var request = RestAssured.given().queryParam("origin", origin).queryParam("client_id", clientId)
        .queryParam("session_state", state);
    if (cookie != null)
      request.cookie("AUTH_SESSION_ID", cookie);
    Response result = request.get(BASE + "/session-check");
    Assertions.assertEquals(200, result.statusCode());
    Assertions.assertEquals("no-store", result.getHeader("Cache-Control"));
    return result.asString();
  }

  @Test
  void iframeIsDiscoverableAndChangesOnlyOnSessionOrAuthorizedOriginChange() {
    Response discovery = RestAssured.get(BASE + "/.well-known/openid-configuration");
    Assertions.assertEquals(200, discovery.statusCode(), discovery.asString());
    String metadata = discovery.jsonPath().getString("check_session_iframe");
    Assertions.assertTrue(metadata.endsWith("/login-status-iframe"));
    Response iframe = RestAssured.get(BASE + "/login-status-iframe");
    Assertions.assertEquals(200, iframe.statusCode());
    Assertions.assertTrue(iframe.asString().contains("postMessage(result,event.origin)"));
    Assertions.assertFalse(iframe.asString().contains("<h1>Check</h1>"));
    Assertions.assertTrue(iframe.getHeader("Content-Security-Policy").contains("'nonce-"));

    Response login = client.submitLogin(OidcTestFixtures.TENANT, OidcTestFixtures.USERNAME,
        OidcTestFixtures.PASSWORD, null);
    String cookie = client.extractAuthSessionCookie(login);
    String state = sessionState(login);
    String origin = "http://localhost";
    Assertions.assertEquals("unchanged", check(cookie, origin, OidcTestFixtures.CLIENT_ID, state));
    Assertions.assertEquals("error",
        check(cookie, "http://unregistered.invalid", OidcTestFixtures.CLIENT_ID, state));
    Assertions.assertEquals("changed", check(null, origin, OidcTestFixtures.CLIENT_ID, state));
    Assertions.assertEquals("changed",
        check(cookie, origin, OidcTestFixtures.WEB_CLIENT_ID, state));

    Response rotated = client.submitSessionConfirm(OidcTestFixtures.TENANT, cookie);
    String newCookie = client.extractAuthSessionCookie(rotated);
    Assertions.assertNotEquals(cookie, newCookie);
    Assertions.assertEquals("unchanged",
        check(newCookie, origin, OidcTestFixtures.CLIENT_ID, state));

    String csrf = RestAssured.given().cookie("AUTH_SESSION_ID", newCookie).get(BASE + "/logout")
        .getCookie("LOGOUT_CSRF");
    Assertions.assertEquals(200, RestAssured.given().contentType(ContentType.URLENC)
        .cookie("AUTH_SESSION_ID", newCookie).cookie("LOGOUT_CSRF", csrf).formParam("csrf", csrf)
        .formParam("client_id", OidcTestFixtures.CLIENT_ID).post(BASE + "/logout").statusCode());
    Assertions.assertEquals("changed", check(newCookie, origin, OidcTestFixtures.CLIENT_ID, state));
  }
}
